// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(uint256 seed) public {
        // The rule: c.version() must report version "1.0.0" regardless of any fuzzed input.
        string memory v = c.version();
        assertTrue(
            bytes(v).length == 5 &&
            bytes(v)[0] == "1" &&
            bytes(v)[1] == "." &&
            bytes(v)[2] == "0" &&
            bytes(v)[3] == "." &&
            bytes(v)[4] == "0",
            "version must be 1.0.0"
        );
    }
}
